// pi-history-search/operations.ts
async function searchReport(ctx, config, params) {
  const base = resolveSessionsBase(config);
  const currentDir = projectDir(base, ctx.cwd);
  const scope = params.scope ?? "project";
  const currentId = ctx.sessionId;
  const exclude = config.excludeCurrentSession && scope !== "current-branch" ? currentId : null;
  let allowed;
  if (scope !== "all" && scope !== "project") {
    const listing = listBranchesInProject(currentDir, currentId, config.branchAliases);
    allowed = branchScopeSessionIds(listing.branches, listing.currentBranchId, scope);
  }
  const dirs = scope === "all" ? listProjectDirs(base).filter((dir) => !params.project || prettyProject(basename3(dir)).toLowerCase().includes(params.project.toLowerCase())) : [currentDir];
  const report = await searchRecall(dirs.map((dir) => ({ dir, current: dir === currentDir, allowed })), config, params, exclude);
  if (params.verbose) {
    for (const dir of dirs) {
      const branches = listBranchesInProject(dir, currentId, config.branchAliases).branches;
      for (const hit of report.hits)
        hit.branch ??= branches.find((b) => b.branchId === hit.sessionId);
    }
  }
  return report;
}

// pi-history-search/worker-entry.ts
var handlers = {
  searchReport,
  findSessionPath,
  getStats,
  grepSession,
  listBranchesInProject,
  listRecent,
  queryProject,
  readSession,
  rebuildProjectIndex,
  updateProjectIndex
};
var MAX_REQUEST_BYTES = 1024 * 1024;
var MAX_RESPONSE_BYTES = 2 * 1024 * 1024;
async function main() {
  let input = "";
  process.stdin.setEncoding("utf8");
  for await (const chunk of process.stdin) {
    input += chunk.toString();
    if (Buffer.byteLength(input) > MAX_REQUEST_BYTES)
      throw new Error("History request exceeds worker IPC limit");
  }
  const request = JSON.parse(input);
  if (!Object.hasOwn(handlers, request.method) || !Array.isArray(request.args))
    throw new Error("Invalid history operation");
  const handler = handlers[request.method];
  const value = await handler(...request.args);
  const response = JSON.stringify({ ok: true, value });
  if (Buffer.byteLength(response) > MAX_RESPONSE_BYTES)
    throw new Error("History result exceeds worker IPC limit; narrow the request");
  process.stdout.write(response);
}
main().catch((error) => {
  process.stdout.write(JSON.stringify({ ok: false, error: error instanceof Error ? error.message.slice(0, 2000) : "History worker failed" }));
  process.exitCode = 1;
}).finally(() => closeAll());
